            tasks.Add(snapshot.SkillEffect.ReadAsync(System.IO.Path.Combine(basePath, $"SkillEffect{fileExtension}")));
            tasks.Add(snapshot.Buff.ReadAsync(System.IO.Path.Combine(basePath, $"Buff{fileExtension}")));
            tasks.Add(snapshot.BuffPool.ReadAsync(System.IO.Path.Combine(basePath, $"BuffPool{fileExtension}")));
            tasks.Add(snapshot.Passive.ReadAsync(System.IO.Path.Combine(basePath, $"Passive{fileExtension}")));
            tasks.Add(snapshot.Stage.ReadAsync(System.IO.Path.Combine(basePath, $"Stage{fileExtension}")));
            tasks.Add(snapshot.StageWave.ReadAsync(System.IO.Path.Combine(basePath, $"StageWave{fileExtension}")));
            tasks.Add(snapshot.StageMonster.ReadAsync(System.IO.Path.Combine(basePath, $"StageMonster{fileExtension}")));
            tasks.Add(snapshot.StageReward.ReadAsync(System.IO.Path.Combine(basePath, $"StageReward{fileExtension}")));
            tasks.Add(snapshot.Chapter.ReadAsync(System.IO.Path.Combine(basePath, $"Chapter{fileExtension}")));
            tasks.Add(snapshot.World.ReadAsync(System.IO.Path.Combine(basePath, $"World{fileExtension}")));

            await Task.WhenAll(tasks);

            SolveCrossReferences(snapshot);

            return snapshot;
        }

        /// <summary>
        /// Makes a snapshot the one the static members read from.
        /// </summary>
        /// <remarks>
        /// The publish on its own, so a caller that loaded one itself can put it in place -
        /// which is what a hot reload does once the next generation has finished reading.
        /// </remarks>
        public static void Publish(Snapshot snapshot)
        {
            // The barrier keeps the writes that built these tables from being seen after the
            // reference to them, so a consumer on another thread reads this load or the one
            // before it - never a mixture.
            System.Threading.Thread.MemoryBarrier();

            Current = snapshot;
        }

        /// <summary>
        /// Read all tables.
        /// </summary>
        /// <remarks>
        /// Safe to call again on a loaded accessor. Nothing published changes until every file
        /// has been read and linked.
        /// </remarks>
        public static async Task ReadAllAsync(
            string basePath, string fileExtension = ".tcb")
        {
            Publish(await LoadAsync(basePath, fileExtension));
        }

        /// <summary>
        /// Solve cross references, among the tables of one read.
        /// </summary>
        private static void SolveCrossReferences(Snapshot snapshot)
        {
        }
    }
